import{_ as n,l as i,o as e,c as s,v as t,p as l,x as r,d as N,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"向量数据库与 ANN","description":"","frontmatter":{"title":"向量数据库与 ANN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vector-db-ann.md","filePath":"cs/vector-db-ann.md","lastUpdated":1789023840000}'),A={name:"cs/vector-db-ann.md"};function c(h,a,E,_,u,m){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="向量数据库与-ann" tabindex="-1">向量数据库与 ANN <a class="header-anchor" href="#向量数据库与-ann" aria-label="Permalink to &quot;向量数据库与 ANN&quot;">​</a></h1><div class="epigraph"><p>近邻在高维不走 B+：HNSW、IVF、PQ 用图或聚类近似。过滤、事务与新鲜度仍是数据库问题，ANN 只替换距离索引。</p><footer>—— 据 Malkov and Yashunin HNSW；Jégou 乘积量化；ANN 库实践</footer></div><p><a href="/cs/timeseries-db">上一课</a>的轴是时间。本课轴是高维向量。计算机栏可能有距离与哈希；数据库进阶钉：<strong>ANN 索引 + 行过滤 + 持久</strong>。不是大模型课：不讲训练 Transformer，只讲存查询嵌入。与全文倒排可混合（稀疏+稠密）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精确 kNN 线性扫或高维树崩。ANN：召回换延迟。HNSW 图、IVF 倒排质心、PQ 压缩距离。缺口是数据库合同：插入删除如何维护图、事务可见性、与 SQL <code>WHERE</code> 先过滤还是先 ANN（pre/post filtering）改变召回。分片：向量切不好，常复制索引或按业务键切。</p><p>WAL：向量大，日志放大；常外置文件+行存 id。BLOB 课的引用模型。</p><p><span class="marginnote">Malkov and Yashunin 的 HNSW；Jégou 等的乘积量化。过滤与召回的权衡是产品核心。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>行：id、向量、元数据。索引：ANN 结构可重建。查询：先元数据 zone/B+ 缩小再 ANN，或 ANN 再过滤（可能不够 k 条）。CDC 更新向量要重建邻接，延迟高。</p><p>与学习索引：都是近似结构+纠正；ANN 纠正是探更多邻居，不是二分键。</p>',10)),(e(),l(p,null,{default:r(()=>[d(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20QV%5B%22%E6%9F%A5%E8%AF%A2%E5%90%91%E9%87%8F%22%5D%20--%3E%20ANN%5B%22HNSW%20%2F%20IVF%22%5D%0A%20%20META%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20PRE%5B%22%E5%85%88%E8%BF%87%E6%BB%A4%E6%88%96%E5%90%8E%E8%BF%87%E6%BB%A4%22%5D%0A%20%20ANN%20--%3E%20IDS%5B%22%E5%80%99%E9%80%89%20id%22%5D%0A%20%20IDS%20--%3E%20HEAP%5B%22%E5%9B%9E%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[N(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MVCC：新向量版本对旧快照不可见，ANN 图若无版本会泄漏——只读重建或按段（LSM 式不可变 ANN 段）。RTO：重建索引时间可超预算，要备副本。</p><p>校准：代价不是页 I/O 公式，是距离计算次数。优化器常把 ANN 当黑盒选择率=k。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Lucene 倒排实现——下一课搜索引擎。也不把向量检索当「语义 SQL 自动」。量化栏不出现。</p><p>后课默认：kNN 走 ANN，谓词策略要测召回。全文检索引擎：词项倒排+打分，可与向量混合检索。</p><p>没有元数据过滤合同的 ANN 会在权限与租户上错召回。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ANN 用图/聚类近似 kNN；过滤顺序影响召回。</li><li>持久、MVCC、分片仍是库问题。</li><li>全文检索引擎下一课。</li><li>出处：HNSW；PQ；倒排课对照。</li></ul>',9))])}const S=n(A,[["render",c]]);export{B as __pageData,S as default};
